import { sql } from "drizzle-orm";
import { customType, timestamp, uuid } from "drizzle-orm/pg-core";

/**
 * Primary key column. IDs are UUIDv7 (time-ordered) generated by the
 * `uuidv7()` SQL function from migration 0000, so rows inserted by Go and by
 * TypeScript get the same kind of ID.
 */
export const id = () => uuid("id").primaryKey().default(sql`uuidv7()`);

/** timestamptz in `Date` mode. */
export const tstz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

export const createdAt = () => tstz("created_at").notNull().defaultNow();

/** Kept current by the `hookline_set_updated_at` trigger (migration 0002). */
export const updatedAt = () => tstz("updated_at").notNull().defaultNow();

/** Raw bytes. postgres.js returns bytea values as Buffers. */
export const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => "bytea",
});

/**
 * An ordered list of name/value pairs. Headers and query strings keep their
 * original order, case and repeated names this way.
 */
export type Pair = [name: string, value: string];
